runtimeProofSources.collector:
def routine_runtime_command(label,args,environment=None,cwd_override=None,seconds=120):
    started=time.monotonic()
    try:
        result=subprocess.run(args,cwd=cwd_override or repo,env=environment,text=True,capture_output=True,timeout=seconds)
    except subprocess.TimeoutExpired as error:
        entry={'label':label,'argv':args,'cwd':str(cwd_override or repo),'failure':'TimeoutExpired','timeoutSeconds':seconds,'stdout':error.stdout.decode('utf-8',errors='replace') if isinstance(error.stdout,bytes) else (error.stdout or ''),'stderr':error.stderr.decode('utf-8',errors='replace') if isinstance(error.stderr,bytes) else (error.stderr or '')}
        routine_evidence['validation']['results'].append(entry)
        routine_evidence['validation']['failures'].append(entry)
        write(str(repo/'docs/c1-routine-tests-evidence.json'),json.dumps(routine_evidence,indent=2)+'\n')
        raise
    entry={'label':label,'argv':args,'cwd':str(cwd_override or repo),'exit':result.returncode,'stdout':result.stdout,'stderr':result.stderr,'durationSeconds':round(time.monotonic()-started,3)}
    routine_evidence['validation']['results'].append(entry)
    if result.returncode!=0:
        routine_evidence['validation']['failures'].append(entry)
    write(str(repo/'docs/c1-routine-tests-evidence.json'),json.dumps(routine_evidence,indent=2)+'\n')
    display(entry)
    return result

runtimeProofSources.receiptCollector:
def retain_routine_streams(records, category, directory):
    receipts=[]
    for index, record in enumerate(records, 1):
        streams={}
        for stream in ['stdout','stderr']:
            content=record.get(stream,'').encode('utf-8')
            path=directory/f'{category}-{index:02d}.{stream}.log'
            path.write_bytes(content)
            streams[stream]={'path':str(path),'bytes':len(content),'sha256':hashlib.sha256(content).hexdigest()}
        receipts.append({'label':record['label'],'exit':record.get('exit'),'streams':streams})
    return receipts

