with tempfile.TemporaryDirectory(prefix='c1-routine-runtime-') as temporary:
    root=Path(temporary)
    for name in ['home','tmp','work']:
        (root/name).mkdir()
    environment={'PATH':'/usr/bin:/bin','HOME':str(root/'home'),'TMPDIR':str(root/'tmp'),'LANG':'C.UTF-8'}
    commands=[
      ('Supported routine JS runner from unrelated cwd',['/usr/bin/node',str(repo/'scripts/run-tests.js'),'test/routines.test.js']),
      ('Direct Node absolute generated routine JS from unrelated cwd',['/usr/bin/node','--test',str(repo/'test/routines.test.js')])
    ]
    observations=[]
    for label,args in commands:
        result=routine_runtime_command(label,args,environment,root/'work')
        if result.returncode!=0:
            routine_runtime_stopped=True
            break
        counts={title:len(re.findall(r'^✔ '+re.escape(title)+r' \(',result.stdout,re.MULTILINE)) for title in routine_runtime_titles}
        assert len(counts)==32 and all(n==1 for n in counts.values())
        assert not list((root/'home').iterdir()) and not list((root/'tmp').iterdir())
        observations.append({'label':label,'eachOriginalCaseExecutedOnce':counts,'ownedHomeAndTmpEmptyAfterRun':True})
    routine_evidence['relativeRuntimeProof']['observations']=observations
